  insert into public.brands (name, website, description, country, status) values ('Blondelight', 'https://blondelight.com', 'Small US direct-to-consumer skincare and body-care brand selling brightening soaps, carrot body creams, body oils and wellness products through its own Shopify store; it runs an open Referral Rewards / brand ambassador program whose own sign-up page pays 10% cash rewards and states there is no cap on earnings.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'skincare'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'general', 'support@blondelight.com', null, null, 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct (own program)', 10, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://partners.blondelight.com/refer.', 'https://partners.blondelight.com/refer', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Blondelight Referral Rewards Program (Own Program, Uncapped)', 'https://partners.blondelight.com/refer', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://partners.blondelight.com/refer', 'brand_site', 'affiliate_program', 'Blondelight''s own affiliate sign-up page (fetched) describes its Referral Rewards Program: anyone creates a free account, shares a personal referral link with friends, family or on social media, and earns 10% cash back on every order placed through the link, redeemable as cash rewards through the account dashboard - not store credit. Under ''Why Join?'' the page states verbatim ''Unlimited Earnings: There''s no cap on how much you can earn!'' - an explicit earnings-cap statement on the brand''s own program page, so commission_cap is recorded as uncapped and commission_rate as 10.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://blondelight.com', 'brand_site', 'brand_overview', 'The brand''s own homepage (fetched) shows a Shopify storefront selling skincare, soaps, body oils and wellness products aimed at uneven skin tone and dark spots, carries an ''Apply to Become our Brand Ambassador'' route, and publishes the support email support@blondelight.com and US phone numbers in its footer. No creator count is published anywhere fetched, so creator_saturation is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 18, 8, 13, 12, 8, 2, '{"compensation": "A published 10% cash rate with a verified no-cap statement on the brand''s own page, though the brand''s small order values limit absolute earnings.", "contact_access": "A support email and two phone numbers are published on the brand''s own homepage.", "credibility": "A very small, low-footprint storefront brand with no meaningful third-party coverage found.", "niche_fit": "Brightening skincare and body care is a real UGC niche, but the product range is narrow.", "opportunity_availability": "Open self-serve sign-up with no follower minimum stated.", "ugc_evidence": "The program explicitly invites social-media sharing and the homepage recruits brand ambassadors, but no tracked creator campaign data was found."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('TULA', 'https://www.tula.com', 'Probiotic skincare brand founded by gastroenterologist Dr. Roshni Raj, known for cleansers, moisturizers and SPF built on probiotic extracts and superfoods; it runs a long-standing affiliate program on ShareASale with an additional ambassador layer for creators.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'skincare'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'ShareASale', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://getlasso.co/affiliate/tula/.', 'https://getlasso.co/affiliate/tula/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'TULA Affiliate Program (ShareASale)', 'https://getlasso.co/affiliate/tula/', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/tula/', 'affiliate_directory', 'affiliate_program', 'Lasso''s TULA program page (fetched) records the affiliate program on ShareASale at 20% per sale with a 90-day cookie, and its join buttons route to account.shareasale.com. Multiple roundups repeat the 20% ShareASale figure, but other fetched sources conflict - Vellko''s skincare list puts TULA at 15% on Impact with a 30-day cookie, and Shopper''s program page says 5-10% - so commission_rate is recorded as null with the conflict documented. A third-party review''s ''no limits to how much you can earn'' wording is not a brand statement and does not count, so the cap is unknown; no creator count is published, so saturation is unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.shopper.com/partnerships/tula-com-affiliate-program', 'affiliate_directory', 'affiliate_program', 'Shopper''s TULA partnership page (fetched) describes the same program as paying a 5-10% payout per sale - one of the conflicting published figures that keeps commission_rate null. Separately, creator-program coverage describes an open ShareASale affiliate plus ambassador program with no stated follower minimum, US-only, aimed at beauty and skincare creators.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 17, 11, 5, 8, 5, '{"compensation": "Every source agrees the program pays well for skincare, but the 20% / 15% / 5-10% conflict means the rate cannot be scored as settled.", "contact_access": "No public partnership email was found on the pages checked; access runs through the ShareASale application.", "credibility": "A major US skincare brand with national retail distribution and a physician founder.", "niche_fit": "Probiotic skincare, acne care and SPF are core SkinTok content categories.", "opportunity_availability": "Open ShareASale application with no stated follower minimum, US-focused.", "ugc_evidence": "A documented ambassador program with product allowances and monthly commission, plus constant creator coverage of the brand."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Huda Beauty', 'https://hudabeauty.com', 'Dubai-founded global makeup brand created by Huda Kattan, famous for Easy Bake loose powder, faux-filter foundations and KAYALI fragrance; it runs its affiliate program on Partnerize with a published default commission, alongside the Huda''s Beauties creator program.', 'United Arab Emirates', 'published') returning id into bid;
