  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Huda Beauty Affiliate Program (Partnerize)', 'https://join.partnerize.com/hudabeauty/en', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://affi.io/m/huda-beauty-uk', 'affiliate_directory', 'affiliate_program', 'The Huda Beauty affiliate program page reproduced on affi.io (fetched) states the program pays commission on every hudabeauty.com purchase through a unique tracking link with a 30-day cookie window, and publishes the commission structure verbatim: default commission 5%, sales using a voucher code 2%, KAYALI products 0%. WhichProgram''s Partnerize network listing (fetched) independently records Huda Beauty on Partnerize at 5% with a 30-day cookie and application required, and the program''s join route is join.partnerize.com/hudabeauty/en. Aggregator figures elsewhere conflict (a per-order euro figure on LinkApprove, 6.48% on Shopper, an up-to-5% creator claim), but the two network-level sources agree on the 5% default, so commission_rate is recorded as 5. No earnings-cap statement is published, so the cap is unknown; no creator count is published, so saturation is unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 29, 18, 9, 6, 8, 5, '{"compensation": "A settled, published 5% default rate, modest for prestige beauty and reduced to 2% on voucher sales.", "contact_access": "Access runs through the Partnerize application; the separate creator program publishes follower requirements but no public email was found.", "credibility": "One of the largest independent beauty brands in the world, founded by a creator.", "niche_fit": "Easy Bake and the complexion line are among the most-demoed products in makeup UGC.", "opportunity_availability": "Open application on Partnerize, plus a creator tier recruiting accounts with 1,000+ followers.", "ugc_evidence": "The brand was built on creator content and runs a structured creator program with missions, early access and featured placements."}'::jsonb);
