  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/anastasia-of-beverly-hill/', 'affiliate_directory', 'affiliate_program', 'LinkClicky''s program listing (fetched) records the Anastasia Beverly Hills affiliate program on Rakuten Advertising at 5% per sale, open across AU, CA, GB, IE, NZ and US, with joining through Rakuten''s LinkShare sign-up. The brand''s ABH Pro tiers are a professional discount program for artists and students, not a commission route, and were not used. No earnings-cap statement is published, so the cap is unknown; no creator count is published, so saturation is unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 16, 8, 5, 8, 5, '{"compensation": "A settled 5% per-sale rate, standard but unspectacular for prestige makeup.", "contact_access": "Network application only; no public creator contact was found on the pages checked.", "credibility": "A prestige category-defining brand with global Sephora and Ulta distribution.", "niche_fit": "Brow and contour products are evergreen tutorial content with constant search demand.", "opportunity_availability": "Open Rakuten application across six markets.", "ugc_evidence": "A creator-era brand with heavy tutorial coverage, though its loudest creator layer is the separate pro scheme."}'::jsonb);
