  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://uppromote.com/affiliate-programs/makeup/', 'affiliate_directory', 'affiliate_program', 'UpPromote''s program directory (fetched) records Yves Rocher''s affiliate program on CJ at 6% commission per sale with a 30-day cookie. Other fetched sources conflict sharply - several directories and roundups say 15% per sale, a Canadian listing via FlexOffers says 16%, and recruiter posts cite 11-13% per order - so commission_rate is recorded as null with the conflict documented. No earnings-cap statement is published, so the cap is unknown; no creator count is published, so saturation is unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 12, 9, 5, 8, 5, '{"compensation": "Even the lowest published figure is workable and several sources cite mid-teens rates, but the conflict keeps the score mid-range.", "contact_access": "Network application only; no public creator contact was found on the pages checked.", "credibility": "France''s number-one beauty brand with 2,000+ stores and a 65-year botanical heritage.", "niche_fit": "Botanical and French-pharmacy beauty is a steady UGC niche, less viral than K-beauty or prestige US brands.", "opportunity_availability": "Open applications through CJ and regional networks across many markets.", "ugc_evidence": "Active affiliate recruitment posts target beauty bloggers in multiple countries, but tracked creator campaign data is thin."}'::jsonb);
