  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.flexoffers.com/affiliate-programs/nyx-professional-makeup-affiliate-program-2/', 'affiliate_directory', 'affiliate_program', 'FlexOffers'' own NYX Professional Makeup program page (fetched) states the payout is 12% of online sales (gift cards excluded) with a 30-day cookie duration, and describes joining through the brand''s affiliate application. Other fetched sources conflict - Lasso''s program page says 4% per sale with a 1-day cookie, and a cosmetics-only roundup puts NYX at 4-8% varying by product category - so commission_rate is recorded as null with the conflict documented. No earnings-cap statement is published, so the cap is unknown; no creator count is published, so saturation is unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 16, 8, 5, 8, 5, '{"compensation": "The headline 12% figure would be excellent for drugstore makeup, but the 4% and 4-8% conflicts leave the real payout unsettled.", "contact_access": "Network application only; no public creator contact was found on the pages checked.", "credibility": "A flagship L''Or\u00e9al brand with global drugstore and Ulta distribution.", "niche_fit": "Butter Gloss and the brow range are perennial creator favorites in bold-color and editorial content.", "opportunity_availability": "Open application through FlexOffers with fast approvals reported for drugstore programs.", "ugc_evidence": "Constant creator coverage and roundup recommendations position NYX as a beginner-friendly affiliate brand."}'::jsonb);
