  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Round Lab TikTok Shop Affiliate Program', 'https://rateful.ai/brand/round-lab', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://rateful.ai/brand/round-lab', 'creator_platform', 'affiliate_program', 'Rateful''s TikTok Shop brand page (fetched) confirms ROUND LAB operates a TikTok Shop affiliate program: about 71% of its estimated $90.2K in TikTok Shop sales in the 30 days to Nov 6, 2026 came through affiliate creators'' videos and LIVEs, across 5,341 items at a $16.89 average price, and any creator with TikTok Shop affiliate access can add its products to their showcase and earn commission on every sale. TikTok Shop rates are set per product by the seller and no program-level rate is published, so commission_rate is null; no cap statement or absolute creator count is published, so cap and saturation are unknown.', 'publicly_reported', now());
