  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Xlash Ambassadors Program (Own Program)', 'https://ambassador.xlash.com/register', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://xlash.com/en-row/pages/xlash-ambassador', 'brand_site', 'affiliate_program', 'Xlash''s own Ambassadors page (fetched via the brand''s site crawl) pitches ''Refer & Get Commissions'': join, receive free Xlash products, share a personal link or code on social media and earn a 30% commission on every sale, with sign-up at ambassador.xlash.com. Other fetched sources conflict with that figure - Affpaying''s program listing describes 25% for the first 30 days then 15%, Lasso''s program page says 10% per sale with a 45-day cookie, and Shopper says 5-10% - so commission_rate is recorded as null with the conflict documented; the recorded route is the brand''s own ambassador program. No earnings-cap statement is published, so the cap is unknown; no creator count is published, so saturation is unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 14, 10, 6, 9, 4, '{"compensation": "Even the lowest published figures are respectable and the brand''s own track claims 30%, but the wide conflict keeps the score mid-range.", "contact_access": "A dedicated ambassador sign-up portal is published on the brand''s own site; no public email was found.", "credibility": "An established Swedish beauty brand sold internationally, with a thinner third-party footprint than US prestige rivals.", "niche_fit": "Lash-growth before-and-after content is a strong UGC format, though the range is a single-category bet.", "opportunity_availability": "Open ambassador application with free product, aimed directly at creators.", "ugc_evidence": "The brand runs a named creator community with free products and social sharing built into the program design."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('END.', 'https://www.endclothing.com/', 'Globally curated menswear, womenswear and sneaker retailer founded in Newcastle, UK, stocking hundreds of fashion and streetwear brands. Its own affiliate page promises a competitive commission structure with unlimited earning potential and runs the program on Impact, which makes it one of this round''s three verified-uncapped programs. No percentage rate is published, so commission_rate is null, and no creator counts are published, so saturation stays unknown.', 'United Kingdom', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fashion'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'affiliates@endclothing.com', null, 'http://www.endclothing.com/row/affiliate-program', 'verified', now());
