  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'END. Affiliate Program (Impact)', 'http://www.endclothing.com/row/affiliate-program', 'http://www.endclothing.com/row/affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'http://www.endclothing.com/row/affiliate-program', 'official_program_page', 'commission_rate', 'END.''s own affiliate program page states a ''Competitive commission structure, with unlimited earning potential.'' That explicit unlimited-earnings statement on the brand''s own page is why commission_cap is recorded as uncapped. No percentage rate is published on the page, so commission_rate is recorded as null rather than guessed.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'http://www.endclothing.com/row/affiliate-program', 'official_program_page', 'creator_program', 'The same page states ''The END. Affiliate Program is on the Impact Platform'' with sign-up from the page, and publishes affiliates@endclothing.com for program questions. No creator counts are published, so creator_saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 15, 17, 13, 8, 5, '{"compensation": "Verified uncapped on the brand''s own page; the unpublished percentage rate keeps this below the top band.", "contact_access": "A dedicated affiliate email (affiliates@endclothing.com) is published on the program page.", "credibility": "Established global retailer founded in Newcastle in 2005 with flagship stores and a large brand catalog.", "niche_fit": "A premier sneaker and streetwear destination - haul, styling and new-drop content is core fashion-creator material.", "opportunity_availability": "Open application through Impact; standard network approval applies.", "ugc_evidence": "Own program page recruits site promoters on Impact; less creator-specific than a Collabs program, so scored mid-range."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Blakely Clothing', 'https://blakelyclothing.com/', 'UK direct-to-consumer fashion and activewear brand selling apparel through UK, US and EU storefronts. Its own affiliates page promises a competitive commission structure with unlimited earning potential and routes creators through Shopify Collabs, making it one of this round''s three verified-uncapped programs. Its collab page advertises only ''up to a 10% commission'', which is a ceiling rather than a base rate, so commission_rate is null, and no creator counts are published, so saturation stays unknown.', 'United Kingdom', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fashion'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'partnerships@blakelyclothing.com', null, 'https://us.blakelyclothing.com/pages/affiliates', 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Shopify Collabs', null, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://us.blakelyclothing.com/pages/affiliates.', 'https://us.blakelyclothing.com/pages/affiliates', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Blakely Clothing Affiliate Program (Shopify Collabs)', 'https://us.blakelyclothing.com/pages/affiliates', 'https://us.blakelyclothing.com/pages/affiliates', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://us.blakelyclothing.com/pages/affiliates', 'official_program_page', 'commission_rate', 'Blakely''s own US affiliates page states ''Competitive commission structure with unlimited earning potential'' and a 30-day cookie, with a ''Join Shopify Collabs'' route. That explicit unlimited-earnings statement on the brand''s own page is why commission_cap is recorded as uncapped.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://blakelyclothing.com/pages/collab', 'official_program_page', 'creator_program', 'Blakely''s own collab page invites fashion and lifestyle bloggers, vloggers, influencers and content creators, publishes partnerships@blakelyclothing.com, and advertises ''up to a 10% commission on every sale''. ''Up to 10%'' is a rate ceiling, not a base rate, so commission_rate is recorded as null. The collab page routes sign-up through UpPromote while the US affiliates page names Shopify Collabs; Shopify Collabs is recorded as the network and the second route is noted here. No creator counts are published, so creator_saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 17, 16, 13, 8, 4, '{"compensation": "Verified uncapped on the brand''s own page; the rate is published only as an ''up to 10%'' ceiling, so no base rate is recorded.", "contact_access": "A partnerships email (partnerships@blakelyclothing.com) is published on the brand''s own pages.", "credibility": "Established UK DTC brand with UK, US and EU storefronts; program terms verified on its own pages.", "niche_fit": "Everyday fashion and activewear staples - outfit, haul and gym-to-street content fits naturally.", "opportunity_availability": "Open application via Shopify Collabs (a parallel UpPromote route is also published).", "ugc_evidence": "Own pages explicitly recruit bloggers, vloggers, influencers and content creators, with campaign partnership opportunities."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('BeachSIM', 'https://beachsim.com/', 'Travel eSIM brand selling data packages for over 150 countries. Its own affiliate page pays 15% commission on every sale plus a flat 100 euros for each approved UGC content piece, states ''No caps. No limits.'' on earnings, and guarantees monthly payouts, making it this round''s strongest verified-uncapped program and its only one built explicitly around paid UGC. Sign-up runs through Impact. The program page states no home country, so country is recorded as Unknown, and no creator counts are published, so saturation stays unknown.', 'Unknown', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', 15, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://affiliate.beachsim.com/.', 'https://affiliate.beachsim.com/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'BeachSIM Affiliate Program (Impact)', 'https://affiliate.beachsim.com/', 'https://affiliate.beachsim.com/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://affiliate.beachsim.com/', 'official_program_page', 'commission_rate', 'BeachSIM''s own affiliate page states affiliates earn ''15% commission for every sale'' plus ''100 euros for each approved UGC content piece'', and states ''No caps. No limits.'', ''No caps or limits on what you can earn'' and ''There''s no limit to how much you can earn'', with guaranteed monthly payouts. Those explicit no-cap statements on the brand''s own page are why commission_cap is recorded as uncapped. The 100-euro UGC payment is a flat bounty per approved content piece, recorded here rather than in the percentage rate.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.facebook.com/reel/1558549749633844/', 'social_post', 'creator_program', 'A BeachSIM walkthrough post shows the affiliate sign-up redirecting to app.impact.com, where applicants identify as a creator and connect Instagram, TikTok or YouTube channels, which is why the network is recorded as Impact. The brand''s own program page states no home country and no creator counts, so country is Unknown and creator_saturation stays unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 19, 19, 8, 9, 3, '{"compensation": "15% commission plus a flat 100-euro bounty per approved UGC piece, with verified no-cap wording on the brand''s own page.", "contact_access": "Sign-up is via the brand''s own affiliate page into Impact; no public affiliate email was verified.", "credibility": "Young, small brand with a thin public footprint beyond its own pages; terms verified on its own page only.", "niche_fit": "A travel eSIM for 150+ countries is a core travel-creator product - connectivity content appears in almost every trip video.", "opportunity_availability": "Open sign-up with guaranteed monthly payouts stated on the program page.", "ugc_evidence": "The program is built around UGC: it pays a flat fee per approved content piece on top of commission and recruits creators by name."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Matador', 'https://matadorequipment.com/', 'Packable adventure and travel gear brand founded in San Francisco in 2014 - pocket blankets, packable backpacks and travel accessories sold direct and through REI and Backcountry. Its affiliate program runs a media/publisher track via AvantLink with a separate creator track via Aspire, but the commission rate is not published anywhere fetched, so commission_rate is null. No earnings-cap statement is published, so the cap stays unknown, and no creator counts are published, so saturation stays unknown.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'AvantLink', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://nomadgear.org/resource/matador/.', 'https://matadorequipment.com/pages/affiliate', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Matador Affiliate Program (AvantLink)', 'https://matadorequipment.com/pages/affiliate', 'https://nomadgear.org/resource/matador/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://nomadgear.org/resource/matador/', 'review_site', 'creator_program', 'NomadGear''s fetched Matador profile describes the ''Matador Affiliate Program (media/publisher track via AvantLink, apply at matadorequipment.com/pages/affiliate; separate creator track via AspireIQ)'' and notes ''Affiliate commission rate isn''t published, so we can''t quote a specific payout for this brand'', which is why commission_rate is recorded as null. AvantLink is recorded as the network because it carries the open application track.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.avantlink.com/?p=8886', 'affiliate_network', 'creator_program', 'AvantLink''s own merchant roundup lists Matador among its affiliate merchants and recounts the brand''s 2014 San Francisco founding around the Pocket Blanket, corroborating both the network and the US base. No earnings-cap statement or creator counts are published in either source, so commission_cap and creator_saturation stay unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 16, 10, 8, 8, 5, '{"compensation": "No rate is published in any fetched source, so compensation scores on program structure only.", "contact_access": "Application is via the brand''s own affiliate page into AvantLink/Aspire; no public affiliate email was verified.", "credibility": "Established brand founded in 2014, sold through REI and Backcountry as well as direct.", "niche_fit": "Packable travel gear is evergreen travel-creator material - packing lists, gear reviews and carry-on content.", "opportunity_availability": "Open AvantLink application; creator track is application-based through Aspire.", "ugc_evidence": "A dedicated creator track via Aspire sits alongside the AvantLink publisher track, and the brand runs large creator storytelling campaigns."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Barehand', 'https://rawwgear.com/', 'Direct-to-consumer fitness brand (Raww) behind Barehand, patented minimalist lifting gloves the brand says 250,000+ lifters train in. Its own VIP Partner Program page pays a published 10% commission per sale on a 7-day cookie, is free to join, and is explicitly built for coaches, creators and gym owners. No earnings-cap statement is published, so the cap stays unknown, and no creator counts are published, so saturation stays unknown.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fitness'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://rawwgear.com/affiliate/.', 'https://rawwgear.com/affiliate/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Barehand VIP Partner Program (Raww)', 'https://rawwgear.com/affiliate/', 'https://rawwgear.com/affiliate/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://rawwgear.com/affiliate/', 'official_program_page', 'commission_rate', 'Raww''s own affiliate page for the ''Barehand VIP Partner Program'' states ''10% commission per sale'', a 7-day referral cookie and a 45-day money-back trial for buyers, and its FAQ confirms ''You earn 10% of the product value of every order you refer'' excluding shipping and tax. No earnings-cap statement appears on the page, so commission_cap is recorded as unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://rawwgear.com/affiliate/', 'official_program_page', 'creator_program', 'The same page says the program is ''Free to join, built for coaches, creators and gym owners'', gives partners their own link plus live stats for visits, referrals and earnings, and cites ''250,000+ lifters'' training in the gloves. No creator counts are published, so creator_saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 17, 13, 8, 9, 4, '{"compensation": "10% published on the brand''s own page; the short 7-day cookie and absence of any cap statement hold the score mid-range.", "contact_access": "Application form on the brand''s own page; no public affiliate email was verified.", "credibility": "Direct-only brand with a large claimed user base (250,000+ lifters, per its own page) and a 45-day money-back guarantee.", "niche_fit": "A single hero product for lifting content - narrow catalog, but a perfect fit for training and grip-content creators.", "opportunity_availability": "Free, open application on the brand''s own site.", "ugc_evidence": "Own program page explicitly names coaches, creators and gym owners as the audience, with a partner dashboard."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Minus33', 'https://minus33.com/', 'New England merino wool apparel company selling base layers, socks and outdoor clothing. Its own affiliates page routes applications through Shopify Collabs and publishes commission tiers ranging from 5% to 10%, with the 5% floor tier recorded as the base rate; top content providers occasionally receive gear to test and review. No earnings-cap statement is published, so the cap stays unknown, and no creator counts are published, so saturation stays unknown.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fashion'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Shopify Collabs', 5, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://minus33.com/pages/affiliates.', 'https://minus33.com/pages/affiliates', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Minus33 Affiliate Program (Shopify Collabs)', 'https://minus33.com/pages/affiliates', 'https://minus33.com/pages/affiliates', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://minus33.com/pages/affiliates', 'official_program_page', 'commission_rate', 'Minus33''s own affiliates page states ''Use Shopify Collabs to apply, manage your partnership, and track your progress'' and answers its commission FAQ with ''We have a couple different tiers of rates ranging from 5%-10%''. The 5% floor of the published tiers is recorded as the base rate. No earnings-cap statement appears on the page, so commission_cap is recorded as unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://minus33.com/pages/affiliates', 'official_program_page', 'creator_program', 'The same page describes Minus33 as ''a small, dedicated company rooted in New England''s rich textile history'', frames affiliates as a community of outdoor enthusiasts, and notes the brand offers its best content providers gear to test and review. No creator counts are published, so creator_saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 14, 11, 8, 9, 4, '{"compensation": "Published tiers of 5%-10% on the brand''s own page; the 5% floor is recorded, which is modest.", "contact_access": "Apply through Shopify Collabs from the brand''s own affiliates page; no public affiliate email was verified.", "credibility": "Small, established New England merino specialist; terms verified on its own page.", "niche_fit": "Merino base layers and apparel are outdoor, ski and travel-wardrobe staples with strong review and layering content.", "opportunity_availability": "Open Collabs application linked from the brand''s own page.", "ugc_evidence": "Shopify Collabs creator route from the brand''s own page, plus gear for top content providers."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Cuyana', 'https://www.cuyana.com/', 'San Francisco luxury direct-to-consumer brand founded in 2011, known for minimalist leather bags and apparel under a ''fewer, better'' philosophy. Its affiliate program runs on Impact (merchant 10312 in FMTC''s feed), but the only rate found in fetched sources is a third-party range of 5-10%, so commission_rate is null with the range documented. No earnings-cap statement is published, so the cap stays unknown, and no creator counts are published, so saturation stays unknown.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fashion'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.fmtc.co/new-fmtc-merchants-include-trugreen-eddie-bauer-us-cavenders-culligan-ufl-shop/.', 'https://www.fmtc.co/new-fmtc-merchants-include-trugreen-eddie-bauer-us-cavenders-culligan-ufl-shop/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Cuyana Affiliate Program (Impact)', 'https://www.fmtc.co/new-fmtc-merchants-include-trugreen-eddie-bauer-us-cavenders-culligan-ufl-shop/', 'https://www.fmtc.co/new-fmtc-merchants-include-trugreen-eddie-bauer-us-cavenders-culligan-ufl-shop/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.fmtc.co/new-fmtc-merchants-include-trugreen-eddie-bauer-us-cavenders-culligan-ufl-shop/', 'affiliate_network', 'creator_program', 'FMTC''s merchant feed lists ''Cuyana | Impact (#10312) | Handbags & Wallets'' with a sign-up route, establishing the program''s network as Impact. A fetched tech-stack crawl of cuyana.com also lists Impact among the brand''s installed tools, corroborating the network.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.Shopper.com/partnerships/cuyana-com-affiliate-program', 'affiliate_directory', 'commission_rate', 'Shopper''s partnership page describes a Cuyana payout of ''5-10%'' per sale. A third-party range is not a published base rate, so commission_rate is recorded as null with the range documented here. No earnings-cap statement or creator counts appear in any fetched source, so commission_cap and creator_saturation stay unknown. A fetched brand profile dates the founding to 2011 in San Francisco.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 12, 10, 7, 7, 5, '{"compensation": "Only a third-party 5-10% range was found, so no base rate is recorded and compensation scores low.", "contact_access": "Join route is the Impact listing surfaced through FMTC; no direct affiliate contact was verified.", "credibility": "Established luxury DTC brand founded in 2011 in San Francisco with a strong editorial profile.", "niche_fit": "Premium leather bags and minimalist essentials are high-intent fashion content - bag reviews, capsule wardrobe and quiet-luxury styling.", "opportunity_availability": "Listed on Impact with a sign-up route; approval terms are not published in fetched sources.", "ugc_evidence": "A standard Impact publisher listing; the brand works with creators, but the fetched program evidence is publisher-framed."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Eagle Creek', 'https://www.eaglecreek.com/', 'Adventure travel gear brand with nearly 50 years in luggage, travel backpacks and packing organizers. Two independent affiliate directories agree on an 8% commission, and a category roundup places the program on CJ Affiliate, but the directories conflict on cookie length (10 vs 30 days), so the cookie is left unrecorded and the network is flagged needs_review. No earnings-cap statement is published, so the cap stays unknown, and no creator counts are published, so saturation stays unknown.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
