  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Eagle Creek Affiliate Program (CJ Affiliate)', 'https://getlasso.co/affiliate/eagle-creek/', 'https://getlasso.co/affiliate/eagle-creek/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/eagle-creek/', 'affiliate_directory', 'commission_rate', 'Lasso''s Eagle Creek profile states an 8% per-sale commission with a 10-day cookie. A second fetched roundup (freeaffiliatemarketingcourse.com''s travel affiliate programs list) independently states ''Default CPA is 8% per sale'' but gives a 30-day cookie, so the 8% rate is recorded on two agreeing sources while the cookie conflict is documented here and left unrecorded.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://whazzuup.com/best-affiliate-programs-by-category-2025/', 'affiliate_directory', 'creator_program', 'A fetched best-programs roundup lists Eagle Creek under Travel Accessories with ''Commission: Available via CJ Affiliate'' and a CJ sign-up link, which is the basis for the recorded network; no brand-domain source confirming the network was fetched, so it is flagged needs_review. No earnings-cap statement or creator counts appear in any fetched source, so commission_cap and creator_saturation stay unknown.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 12, 12, 7, 8, 5, '{"compensation": "8% agreed by two independent directories; cookie terms conflict between them, holding the score mid-range.", "contact_access": "Join route runs through the network listing; no direct affiliate contact was verified.", "credibility": "Category leader in adventure travel gear for nearly 50 years, per the fetched roundup.", "niche_fit": "Luggage and packing organizers are evergreen travel content - packing demos, gear comparisons and carry-on guides.", "opportunity_availability": "Open network program with monthly payouts reported by directories.", "ugc_evidence": "Publisher-framed program that directories pitch to travel bloggers; no dedicated creator track was found in fetched sources."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Sea Eagle', 'https://www.seaeagle.com/', 'US inflatable boat and kayak maker headquartered in Port Jefferson, New York. Its own affiliate page pays a published 9% commission on average orders over $650 with an unusually long 120-day cookie, run through AvantLink and aimed at outdoors websites, blogs and YouTube channels. No earnings-cap statement is published, so the cap stays unknown, and no creator counts are published, so saturation stays unknown.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'AvantLink', 9, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.seaeagle.com/Affiliate.', 'https://www.seaeagle.com/Affiliate', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Sea Eagle Affiliate Program (AvantLink)', 'https://www.seaeagle.com/Affiliate', 'https://www.seaeagle.com/Affiliate', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.seaeagle.com/Affiliate', 'official_program_page', 'commission_rate', 'Sea Eagle''s own affiliate page states ''9% commission on every sale (excluding outboard motors, solar panels, and Scotty products)'', ''Average order over $650'' and ''120 Day Cookies'', and says the program is partnered with AvantLink, which handles payments, tracking and reporting. No earnings-cap statement appears on the page, so commission_cap is recorded as unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.seaeagle.com/Affiliate', 'official_program_page', 'creator_program', 'The same page opens with ''Do you have a website, blog or YouTube channel related to the great outdoors?'' and states joining is free via AvantLink; it publishes the company''s headquarters at 19 N. Columbia St., Port Jefferson, NY, USA. No creator counts are published, so creator_saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 21, 13, 14, 9, 9, 5, '{"compensation": "9% on average orders over $650 with a 120-day cookie - strong per-sale economics, verified on the brand''s own page.", "contact_access": "Headquarters address and phone are published on the program page itself; joining is via AvantLink.", "credibility": "Long-established US boat maker with a BBB-listed headquarters; terms verified on its own page.", "niche_fit": "Inflatable kayaks and boats fit adventure-travel and outdoors content well, though the niche is narrower than luggage or apparel.", "opportunity_availability": "Free to join, open application through AvantLink.", "ugc_evidence": "Own page recruits outdoors websites, blogs and YouTube channels by name; publisher-framed rather than a creator platform."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Feetures', 'https://feetures.com/', 'US performance running sock brand with targeted compression, an anatomical fit and a lifetime guarantee. Its creator program runs through an affiliate network that no fetched source names, and published rates conflict - one directory states 8% while two others state 10% - so commission_rate is null with the conflict documented. No earnings-cap statement is published, so the cap stays unknown, and no creator counts are published, so saturation stays unknown.', 'United States', 'published') returning id into bid;
