  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Feetures Affiliate Program', 'https://getlasso.co/affiliate/feetures/', 'https://getlasso.co/affiliate/feetures/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/feetures/', 'affiliate_directory', 'commission_rate', 'Lasso''s Feetures profile states an 8% per-sale commission with a 30-day cookie, while a fetched socks-program roundup (runtheaffiliatemarket.com) and a deals-network listing (linkmydeals.com) both state 10%. Because the published rates conflict, commission_rate is recorded as null with the conflict documented here. The 30-day cookie is the one term the sources agree on.', 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.bravodm.com/brands/feetures', 'review_site', 'creator_program', 'BravoDM''s checked Feetures creator-program page states ''The program runs through an affiliate network'' without naming it, which is why the network is recorded as not publicly named. The brand is described across fetched sources as America''s premier running sock brand with a lifetime guarantee. No earnings-cap statement or creator counts appear in any fetched source, so commission_cap and creator_saturation stay unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 13, 9, 7, 8, 5, '{"compensation": "Published rates conflict (8% vs 10%), so no rate is recorded and compensation scores low.", "contact_access": "Join route is via directory listings into the unnamed network; no direct affiliate contact was verified.", "credibility": "Established US running brand with a lifetime guarantee on its socks.", "niche_fit": "Performance running socks are a run-and-fitness creator staple - gear lists, race prep and everyday training content.", "opportunity_availability": "Network application with manual approval reported by directories.", "ugc_evidence": "A checked creator-program page exists and the program runs through a network, but no creator-specific terms were published in fetched sources."}'::jsonb);
