  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'BodyBio Creator/Influencer affiliate program via Superfiliate - 20% commission published on the brand''s own affiliate page', 'https://bodybio.com/pages/affiliate', 'https://bodybio.com/pages/affiliate', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://bodybio.com/pages/affiliate', 'brand_site', 'affiliate_program', 'BodyBio''s own affiliate page runs two tracks. The Creator/Influencer Affiliate track - the consumer creator route recorded here - pays 20% commission with a 15% audience discount code that applies to all products including first-time subscription orders and is valid for first-time and returning customers; the program is managed through Superfiliate. A separate Practitioner Affiliate track (15%, private clients only, strictly prohibited from being shared on online platforms) is not the route recorded here.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/bodybio/', 'third_party', 'commission_rate', 'Third-party figures conflict with the brand''s own page - Lasso lists BodyBio at 3% to 10% per sale and Shopper lists 5-10% - against the 20% creator-track rate published on BodyBio''s own current affiliate page; the brand''s own page governs and the dissent is documented here.', 'needs_review', now());
