  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://pulsetto.tech/pages/affiliate', 'brand_site', 'affiliate_program', 'Pulsetto''s own affiliate page states commissions start at 5% with potential increases based on promotional quality and volume, a $10 minimum payment paid 20 days after a 30-day locking period following the month-end of the sale, creatives and codes provided, no geographic limitations, and registration through Impact - the page''s register link points to app.impact.com.', 'verified', now());
