  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Love Wellness TikTok Shop affiliate program - brand-run GMV challenges for TikTok Shop affiliates in the brand''s own contest rules; rate set per product in TikTok Shop', 'https://lovewellness.com/pages/tiktok-contest-2025-official-rules', 'https://lovewellness.com/pages/tiktok-contest-2025-official-rules', 'unverified', 'ugc');
