  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://resona.health/join-our-affiliate/', 'brand_site', 'affiliate_program', 'Resona Health''s own affiliate page offers a flat 20% commission on referred sales, paid monthly via PayPal around the 1st of the month after a 30-day delay for returns, with no minimum payout threshold and 21-day attribution; customers buying through an affiliate link receive a doubled 60-day money-back guarantee and entry into a monthly sweepstakes, and affiliates get a dashboard with links, banners, images and videos.', 'verified', now());
