  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.skratchlabs.com/pages/affiliates', 'brand_site', 'affiliate_program', 'Skratch Labs'' own affiliates page (''the Skratch Collective'') offers members a personal affiliate code and tracking link and commission on every first-time purchase made through their code, plus a personal restock discount, early access to product drops and a chance to be featured in brand content; the page targets people who train, race, coach or create in endurance sports, gives a sub-5-minute application, and publishes the contact info@skratchlabs.com. No commission percentage is published on the page, so the rate is recorded null.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 14, 9, 12, 7, 5, '{"compensation": "Commission on first-time purchases is confirmed on the brand''s own page but no percentage is published, so the rate is honestly null.", "contact_access": "A contact email (info@skratchlabs.com) is published directly on the affiliates page alongside the application.", "credibility": "A long-established Boulder sports-nutrition brand with national specialty retail presence.", "niche_fit": "Endurance sports nutrition is a staple food-and-drink content niche with strong race-day and training angles.", "opportunity_availability": "Application-based and aimed at people already active in endurance sports communities.", "ugc_evidence": "A named Collective with codes, tracking links and brand featuring for members shows a genuine creator and athlete channel."}'::jsonb);
