  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Amy Myers MD affiliate and influencer program via Impact - brand-published tracks; rates conflict across sources, recorded null', 'https://www.amymyersmd.com/pages/affiliates', 'https://www.amymyersmd.com/pages/affiliates', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ammd-next.netlify.app/pages/affiliates', 'brand_site', 'affiliate_program', 'The brand''s affiliate and influencer program copy states the program is hosted on the Impact network, with an Affiliate track paying up to 15% commission and an Influencer track paying up to 10% plus free product, both with a custom $10-off customer promo, 30-day last-touch attribution, creative support and a dedicated account manager; the influencer track requires a minimum of 2,500 followers on at least one social channel, and questions go to partners@amymyersmd.com. Flagged needs_review because the detailed copy was found on the brand''s staging subdomain; the live site carries the affiliates page at amymyersmd.com/pages/affiliates.', 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/amy-myers-md/', 'third_party', 'commission_rate', 'Published rates conflict - linkclicky and Lasso report 10% per sale via Impact, affjumbo reports 12%, and affpaying reports figures from 15% to 25% - and the brand publishes no single settled rate, so commission_rate is recorded null with the conflict documented here.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 14, 9, 11, 7, 5, '{"compensation": "Published figures conflict (10% vs 12% vs up to 15% vs 25%) and no single rate is settled by the brand, so the rate is honestly null; no cap statement is published.", "contact_access": "A partnerships email (partners@amymyersmd.com) is published in the brand''s program copy, flagged needs_review as it was found on the staging copy.", "credibility": "A well-known functional-medicine brand founded in 2010 by a bestselling author-physician.", "niche_fit": "Physician-formulated gut, thyroid and autoimmune supplements fit health-education content squarely.", "opportunity_availability": "The influencer track requires at least 2,500 followers on one channel; the affiliate track is aimed at health-focused publishers.", "ugc_evidence": "Separate affiliate and influencer tracks with free product, promo codes and a dedicated account manager show a structured creator program."}'::jsonb);
