  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://verdanttea.com/verdant-tea-affiliate-program', 'brand_site', 'affiliate_program', 'Verdant Tea''s own affiliate page states the program runs through AWIN: partners sign up on the brand''s affiliate page, email the brand for a verification code if they are new to AWIN, and once approved earn commission on all sales generated through their banner or link. The page publishes no commission rate and no cap statement, so the rate is recorded null and the cap stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 12, 9, 10, 8, 5, '{"niche_fit": "Single-origin specialty tea fits tea ritual, food and drink education content well.", "ugc_evidence": "A standing AWIN program recruited from the brand''s own page, aimed at blogs and websites in the tea community.", "compensation": "No commission rate is published on the brand''s page or in a fetched network listing, so the rate is honestly null; no cap statement is published.", "contact_access": "The brand invites direct email contact from its affiliate page for AWIN verification codes, alongside the application route.", "opportunity_availability": "Open signup through AWIN, subject to approval.", "credibility": "A long-running, well-regarded farmer-first tea company with deep sourcing transparency."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Fera Pets', 'https://ferapets.com', 'Veterinarian-founded pet wellness brand making science-backed supplements for dogs and cats (founded 2017 by veterinarian Dr. Michelle Dulake). It recruits creators through three live routes at once: a GRIN creator program paying 20% per sale with free product, an Awin affiliate program that expressly targets pet influencers and creators, and its own Ambassador Program paying cash commissions from $10 per order.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'pets'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'ambassadors@ferapets.com', 'https://app.grin.ai/brands/ferapets.com', 'https://www.bravodm.com/brands/ferapets', 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'GRIN', 20, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://app.grin.ai/brands/ferapets.com.', 'https://app.grin.ai/brands/ferapets.com', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Fera Pets Creator Program on GRIN — 20% per sale plus free product; Awin affiliate program also recruiting pet creators', 'https://app.grin.ai/brands/ferapets.com', 'https://app.grin.ai/brands/ferapets.com', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/95157', 'official_site', 'affiliate', 'Fera Pets'' official Awin merchant profile fetched in full: the brand is ''actively looking to partner with'' pet influencers and creators, veterinarians and vet tech creators, pet wellness publishers and TikTok/Instagram/YouTube/blog creators, with ''dedicated affiliate support'' and seasonal campaign opportunities. The Awin profile publishes no commission rate, cap statement or creator count.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://app.grin.ai/brands/ferapets.com', 'directory', 'affiliate', 'Fera Pets'' GRIN Marketplace profile lists one active partner program: ''20% per sale — earn commission on every sale you drive'', free product (Longevity Soft Chews for Dogs), and one deliverable (1 Instagram Reel within 30 days of receiving the gift), with a creative brief on application. The same profile lists the brand''s external Ambassador Program: ''Earn cash commissions starting at $10 per order, receive a custom promo code... 7-day cookie period.'' The recorded route is the GRIN creator program at 20%; the ambassador floor and the Awin route are documented here. Creator pitches are taken at ambassadors@ferapets.com per the brand''s creator-program listings. No earnings-cap statement and no creator count are published on any fetched page, so cap and saturation stay unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 18, 17, 12, 8, 4, '{"compensation": "20% per sale on GRIN is top-band for pet supplements; the ambassador route''s $10-per-order floor is weaker, and no cap statement is published anywhere.", "contact_access": "A published creator email (ambassadors@ferapets.com) plus GRIN and Awin application routes \u2014 several ways in.", "credibility": "Founded 2017 by a veterinarian, present on major networks with consistent program reporting; a mid-size brand, so a point is held back.", "niche_fit": "Vet-formulated dog and cat supplements are core pet-creator content, and the brand is social-first with an engaged TikTok/Instagram audience.", "opportunity_availability": "The GRIN program is listed active now and the Awin profile says the brand is actively recruiting; the GRIN route requires one Reel deliverable per gift.", "ugc_evidence": "Three simultaneous creator routes (GRIN program with a written creative brief, an Awin profile naming influencers and UGC channels, and an ambassador scheme) \u2014 the strongest creator evidence in this group."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Omi', 'https://omi.me', 'AI-powered wearable that captures conversations and automatically generates summaries and action items. Its own affiliate program publishes a 30% commission rate with a 30-day cookie, a $10 minimum payout and monthly payouts via Stripe Connect, and states that 1,450+ affiliates already promote it — an absolute count that puts creator saturation at high.', 'United States', 'published') returning id into bid;
