  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://affiliate.omi.me/', 'https://affiliate.omi.me/', 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct', 30, 'Commission cap: not stated in any published source found — needs review. Creator saturation: high (see evidence). Rate as reported by https://affiliate.omi.me/.', 'https://affiliate.omi.me/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Omi Affiliate Program — 30% per sale on an AI conversation wearable, instant sign-up, Stripe payouts', 'https://affiliate.omi.me/', 'https://affiliate.omi.me/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://affiliate.omi.me/', 'official_site', 'affiliate', 'Omi''s own affiliate page fetched in full. Its ''Transparent commission structure'' block lists: ''30%, Commission rate, 30, Day cookie window, $10, Minimum payout, Monthly, Payout schedule'', and the body repeats ''30% per sale is among the highest in wearable tech... One referral can earn you $20-30+.'' Headlines phrase the same figure as ''Earn up to 30% commission'', which is documented here; the recorded 30 is the rate the program''s own structure block publishes. Sign-up is free with instant link and coupon code, real-time dashboard, payouts to bank via Stripe Connect. The page states ''1,450+ affiliates'' and ''2,500+ referral orders'' — an absolute four-figure affiliate count, so creator_saturation is recorded as high. No earnings-cap statement is published, so cap stays unknown. Country is recorded as the brand''s primary market (USD/Stripe US storefront); no HQ address appears on the fetched page.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 15, 19, 9, 7, 3, '{"compensation": "30% per sale is the highest published rate in this group, with a low $10 payout threshold and monthly Stripe payments; only the absence of a cap statement keeps it off a perfect mark.", "contact_access": "Open self-serve sign-up on the brand''s own affiliate subdomain; no published partnerships email.", "credibility": "A young AI-hardware startup; the program terms are unusually transparent, but the track record is short next to established brands.", "niche_fit": "An AI wearable that demos itself in a 30-second clip (talk, then show the summary it wrote) is natural tech and productivity creator content.", "opportunity_availability": "Joining is instant, but the program already counts 1,450+ affiliates, so new creators compete in a crowded field.", "ugc_evidence": "A standing own-brand affiliate program with instant links and a live dashboard; the evidence is the program page itself rather than a creator-branded campaign."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Rocco & Roxie', 'https://roccoandroxie.com', 'Family-owned and operated US brand of pet products, best known for its Professional Strength Stain & Odor Eliminator. Its Ambassador Program pays 20% commission on every order placed through an ambassador''s referral link or personal coupon code (followers get 10% off with the code), plus free product when new products launch.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'pets'), true);
