  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct', 20, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://roccoandroxie.com/pages/ambassadorrr.', 'https://roccoandroxie.com/pages/ambassadorrr', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Rocco & Roxie Ambassador Program — 20% commission on link and code orders, followers save 10%', 'https://roccoandroxie.com/pages/ambassadorrr', 'https://roccoandroxie.com/pages/ambassadorrr', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://roccoandroxie.com/pages/ambassadorrr', 'official_site', 'affiliate', 'Rocco & Roxie''s own Ambassador Program page fetched in full: ''ALL ROCCO & ROXIE AMBASSADORS WILL RECEIVE ◦ 20% commissions on orders using your referral link... We will pay you 20% commissions on anyone you refer that makes a purchase on roccoandroxie.com... you will earn 20% of their order total before sales tax and shipping.'' Ambassadors also get a personalized coupon code (followers save 10%, ambassador earns 20%), free product at launches, and points redeemable for gift cards on top. Ambassadors are asked to post about giveaways and use the program hashtags — a social-creator program, not a publisher network listing. The page names no third-party platform, so network is recorded as brand direct. No earnings-cap statement and no creator count are published, so cap and saturation stay unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 16, 17, 9, 9, 4, '{"compensation": "20% of the order total is top-band for pet supplies and applies to both link and code sales; no cap statement is published.", "contact_access": "Open application on the brand''s own page; no published partnerships email, so access runs through the form.", "credibility": "A long-running family brand whose flagship product is a category best-seller in US pet retail; program terms are plainly published.", "niche_fit": "A hero stain-and-odor product with a visible before/after is proven pet-cleaning UGC material, and the wider catalog suits everyday dog and cat content.", "opportunity_availability": "Recruiting now on the brand''s own site with no follower minimum stated on the fetched page.", "ugc_evidence": "A creator-built ambassador program with hashtags, giveaway posts and free launch product \u2014 designed for social creators rather than adapted from a publisher program."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Vital Essentials', 'https://www.vitalessentials.com', 'Freeze-dried raw pet food and treats built on butcher-cut protein — raw food, freeze-dried treats and chews for dogs and cats. Its affiliate program runs on Impact under the banner ''Join the Pack, Fuel the Movement'', with a published default rate of 10% and monthly performance bonus tiers above it.', 'United States', 'published') returning id into bid;
