  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Vital Essentials Affiliate Program on Impact — 10% default on freeze-dried raw pet food, bonus tiers above', 'https://www.vitalessentials.com/partner-with-us', 'https://www.vitalessentials.com/partner-with-us', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.vitalessentials.com/partner-with-us', 'official_site', 'affiliate', 'Vital Essentials'' own partner page fetched: ''Join the Pack, Fuel the Movement — Help more pets thrive by sharing butcher-cut, protein-packed nutrition with your audience by joining our affiliate program'', with its Apply Now button routing to app.impact.com, confirming the program and the Impact network from the brand''s own site. The 10% figure is the program''s published default rate, publicly reported from the program''s Impact contract terms (a contract-terms screenshot shared publicly by the brand''s affiliate team), with monthly performance bonus tiers paying above the default; the brand page itself does not print the rate, so confidence is publicly_reported rather than verified. No earnings-cap statement and no creator count are published, so cap and saturation stay unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 15, 14, 9, 9, 4, '{"compensation": "10% default is mid-range for pet food, lifted by monthly performance bonus tiers on a consumable with strong repeat purchase behaviour.", "contact_access": "Public partner page with a direct Impact application route; no published partnerships email.", "credibility": "An established US raw pet food brand with national retail distribution; program existence is brand-verified even though the rate is publicly reported.", "niche_fit": "Raw and freeze-dried feeding is one of the most content-rich pet niches \u2014 meal prep, transitions and results videos map directly onto dog and cat creator audiences.", "opportunity_availability": "Program is live and accepting applications through Impact now.", "ugc_evidence": "The brand''s own partner page pitches the program at audience owners (''sharing... with your audience''), and the program runs on Impact with performance tiers; the rate evidence is reported rather than brand-published."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Smithey Ironware', 'https://smithey.com/', 'Premium American-made cast iron and carbon steel cookware — skillets, griddles and Dutch ovens machined smooth in Charleston, South Carolina, and sold as heirloom pieces that improve with use. Its affiliate program runs on Impact at 10% per sale.', 'United States', 'published') returning id into bid;
