  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/smithey-ironware/', 'directory', 'affiliate', 'LinkClicky''s Smithey Ironware listing fetched in full: ''Affiliate Platform: Impact'', ''Commission: 10% per sale'', website smithey.com, with its FAQ repeating ''The commission rate for Smithey Ironware is 10% per sale... This is just what''s officially listed with their affiliate program as the payout'' and sign-up routing to app.impact.com. A Shopper partnership listing''s ''up to 15%'' figure is a ceiling, not the base rate, and is documented here rather than recorded. No earnings-cap statement and no creator count are published, so cap and saturation stay unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 13, 14, 8, 8, 5, '{"compensation": "10% per sale is solid for cookware, and Smithey''s premium price points make the per-order commission meaningful.", "contact_access": "Application through Impact and the directory listing; no published partnerships email was found on a fetched page.", "credibility": "A well-established US maker with national retail presence and consistent program reporting \u2014 fully checkable.", "niche_fit": "Cast iron cooking, seasoning and restoration content is a durable home-cooking niche, and Smithey''s mirror-smooth finish is a visual differentiator creators can show, not just say.", "opportunity_availability": "Listed as an active Impact program with applications open now, subject to brand approval.", "ugc_evidence": "A standing Impact program in the cooking niche promoted by kitchen bloggers and reviewers; directory-level evidence rather than a creator-branded page."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Small Pet Select', 'https://shop.smallpetselect.com', 'Small-animal specialist selling farm-fresh hay, food, toys and care supplies for rabbits, guinea pigs and other small pets. Its Ambassador Program, powered by Refersion, is open to rescues, customers, affiliates and influencers and pays 10% commission on new-customer orders with a 30-day cookie and monthly PayPal payouts.', 'United States', 'published') returning id into bid;
