  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Small Pet Select Ambassador Program on Refersion — 10% on new-customer orders for small-pet creators and rescues', 'https://smallpetselectus.refersion.com/?oid=78445', 'https://smallpetselectus.refersion.com/?oid=78445', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://smallpetselectus.refersion.com/?oid=78445', 'official_site', 'affiliate', 'Small Pet Select''s own US Refersion portal fetched in full: ''Our Small Pet Select Ambassador Program is for rescues, happy customers, affiliates, and influencers, both big and small.'' Highlights: ''Commission Rate: 10% for new customers'', ''Cookie: 30 days'', ''Monthly payments via PayPal''; the Commission Fees section repeats the standard rate of 10% for new customers on a qualified purchase via link or approved email trigger, applications are reviewed within 3–5 business days, and promotion is restricted to ''legitimate channels of influence'' (no paid traffic or coupon sites). A separate UK program exists on Refersion at a 15% base and is not the route recorded here. No earnings-cap statement and no creator count are published, so cap and saturation stay unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 14, 13, 9, 8, 4, '{"compensation": "10% on new-customer orders is fair for consumables; the repeat-order rate is not published, which holds the score mid-band.", "contact_access": "Public application on the brand''s Refersion portal with a stated 3\u20135 business day review; no public email survived redaction on the fetched page.", "credibility": "A long-running specialist retailer with a loyal small-pet community and plainly published program terms.", "niche_fit": "Rabbits, guinea pigs and other small pets are an underserved creator niche next to dogs and cats, and hay/food is repeat-purchase content by nature.", "opportunity_availability": "Open now to affiliates and influencers ''both big and small'', subject to application review.", "ugc_evidence": "An ambassador program that names influencers as a partner type and supplies banners and creatives; evidence is the brand''s own program portal."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Velotric', 'https://www.velotricbike.com', 'US e-bike brand selling commuter, fat-tire and folding electric bikes direct to consumers. Its affiliate program runs on Impact at 7% per sale on a 30-day referral period — a rate its own referral terms independently confirm for e-bikes, with accessories at 5%.', 'United States', 'published') returning id into bid;
