  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://app.impact.com/advertiser-campaign-info/Velotric-Ebike.brand?c=___9XpvYq1Sf0-BHmwgf1a9MNMe5LqVPpQ9&lang=en', 'directory', 'affiliate', 'Impact''s own Velotric Ebike campaign listing publishes: ''Online Sale — Payout 7%'', ''Referral Period 30 days'', payout scheduled 1 month and 15 days after month end. The brand''s own Refer a Friend terms on velotricbike.com independently state the same structure — 7% commission on eligible eBikes, 5% on accessories, earnings held 45 days, paid via PayPal from a $50 balance — so the recorded 7 is the e-bike rate with the 5% accessory rate documented here. No earnings-cap statement and no creator count are published, so cap and saturation stay unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 13, 13, 8, 8, 4, '{"compensation": "7% looks modest until the ticket size lands \u2014 roughly $70+ on a $1,000 bike \u2014 and the rate is corroborated by two independent sources.", "contact_access": "Application through Impact''s published campaign page; no published partnerships email was found on a fetched page.", "credibility": "An established US DTC e-bike brand with consistent terms across its network listing and its own site.", "niche_fit": "E-bike reviews, range tests and commute content are a growing tech-adjacent creator niche, and Velotric''s price points sit where comparison videos convert.", "opportunity_availability": "Listed as an active Impact program with applications open now.", "ugc_evidence": "A standing Impact program plus a consumer referral scheme on the brand''s own site; evidence is network-level rather than a creator-branded program page."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Four Leaf Rover', 'https://fourleafrover.com', 'Natural dog-health brand selling human-grade supplements formulated for dogs — mushroom, gut, joint and detox products — backed by a large holistic dog-care content community. Its affiliate program runs on Impact with a published 5%–15% commission range on new-customer orders and a 30-day cookie; the floor of the range is what is recorded.', 'United States', 'published') returning id into bid;
