  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Four Leaf Rover Affiliate Program on Impact — 5%–15% on new-customer orders, 30-day cookie, in-house affiliate team', 'https://fourleafrover.com/four-leaf-rover-affiliate-sign-up', 'https://fourleafrover.com/four-leaf-rover-affiliate-sign-up', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://fourleafrover.com/four-leaf-rover-affiliate-sign-up', 'official_site', 'affiliate', 'Four Leaf Rover''s own affiliate sign-up page fetched in full: ''For every new customer you drive to Four Leaf Rover, you''ll earn a generous commission'', support from ''our dedicated in-house affiliate team'', and an FAQ confirming ''We work with Impact to facilitate our tracking, reporting, and payment... Impact then grants you commissions on all new customer orders that occur within your 30 day cookie window'', with Join buttons routing to app.impact.com. Impact''s own campaign listing for the brand publishes ''Online Sale: 5%-15%''. Because the published rate is a range, the recorded 5 is its floor, with the full range documented here. No earnings-cap statement and no creator count are published, so cap and saturation stay unknown. Country is recorded as the brand''s primary market (US storefront and US contact number); no HQ address appears on the fetched pages.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 14, 9, 10, 8, 4, '{"compensation": "Only the 5% floor of a 5%\u201315% range can be recorded, and commissions apply to new customers only \u2014 the weakest compensation evidence among this group''s Impact programs.", "contact_access": "A detailed program page with FAQ, phone number and live chat on the brand''s own site, plus the Impact application route.", "credibility": "A long-running brand with a large publishing arm in holistic pet care; program mechanics are confirmed on its own page and Impact''s listing.", "niche_fit": "Holistic dog health is a passionate, content-driven niche, and the brand''s own education community shows exactly the audience creators would sell into.", "opportunity_availability": "Free to join with applications reviewed regularly, per the brand''s own page.", "ugc_evidence": "A brand-run program page aimed at bloggers and communities with an in-house affiliate team, tracked on Impact; not a creator-branded campaign, so mid-band."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Printique', 'https://www.printique.com', 'Adorama''s professional photo lab: custom prints, metal prints, photo books, albums, cards, calendars and wall decor, handmade to order. Its affiliate program lists ''Unlimited Earnings'' as a headline benefit on the brand''s own affiliate page — a verified uncapped program — with sign-up routed through Partnerize and a 30-day cookie.', 'United States', 'published') returning id into bid;
