  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Partnerize', null, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://www.printique.com/company/affiliate/.', 'https://www.printique.com/company/affiliate/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Printique Affiliate Program on Partnerize — ''Unlimited Earnings'' stated on the brand''s own page (verified uncapped); rate to confirm at sign-up', 'https://www.printique.com/company/affiliate/', 'https://www.printique.com/company/affiliate/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.printique.com/company/affiliate/', 'official_site', 'affiliate', 'Printique''s own affiliate page fetched in full. Its Benefits list reads: ''Free to join'', ''Unlimited Earnings'', ''30 Day cookies'', with access to prints, metal prints, photobooks, albums, cards, calendars and wall decor, plus banners, deep-linking and a dedicated affiliate team. The explicit unlimited-earnings statement sits on the brand''s own page, so commission_cap is recorded as uncapped. The page''s Join Now button routes to join.partnerize.com, so the current network is Partnerize. The RATE is left null because published figures conflict: the brand''s legacy affiliate FAQ states a default of 10% (5% on existing customers, 10% on new) under older Impact Radius management, while the current Partnerize profile reported by affcobra states 20% — the conflict is documented here rather than resolved by guessing. No creator count is published, so saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 13, 12, 8, 8, 5, '{"compensation": "Verified uncapped on the brand''s own page, which is rare and valuable, but the commission rate itself is unpublished in current terms (10% legacy vs 20% reported), so creators cannot price it before applying.", "contact_access": "Program page and Partnerize application are public, with a dedicated affiliate team promised; no published email on the fetched page.", "credibility": "Adorama''s own lab \u2014 one of the most established names in US photo retail \u2014 with the uncapped claim on its own domain.", "niche_fit": "Photo prints, books and wall decor fit home-decor and photography creators \u2014 gallery walls, family photo projects and gift content \u2014 though it is a narrower UGC niche than this group''s leaders.", "opportunity_availability": "Free to join and recruiting now through Partnerize.", "ugc_evidence": "A standing program with banners, deep-linking and a dedicated affiliate team; pitched at photography publishers more than social creators, so mid-band."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Lomi', 'https://lomi.com/', 'Countertop composter by Pela that turns food scraps into nutrient-rich soil within hours, aimed at households that want composting without a garden. Its affiliate program runs on Impact and pays a flat $20 per sale; because the payout is a flat bounty rather than a percentage, no percentage rate is recorded.', 'United States', 'published') returning id into bid;
