  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Lomi Affiliate Program on Impact — flat $20 per sale on the countertop composter', 'https://linkclicky.com/affiliate-program/lomi/', 'https://linkclicky.com/affiliate-program/lomi/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/lomi/', 'directory', 'affiliate', 'LinkClicky''s Lomi listing fetched in full: ''Affiliate Platform: Impact'', ''Commission: $20 per sale'', website lomi.com, with its FAQ repeating ''The commission rate for Lomi is $20 per sale. This is just what''s officially listed with their affiliate program as the payout'' and sign-up routing to app.impact.com. The payout is a flat bounty, so commission_rate is recorded as null with the $20 flat documented here (the flat-bounty precedent). No earnings-cap statement and no creator count are published, so cap and saturation stay unknown. Country is recorded as the brand''s primary market; the listing gives regions as worldwide.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 12, 12, 7, 8, 4, '{"compensation": "A flat $20 per sale is predictable and decent against the unit price, but it does not scale with bundles or accessories the way a percentage would.", "contact_access": "Application via Impact and the directory listing; no published partnerships email was found on a fetched page.", "credibility": "A widely retailed product from Pela with consistent directory reporting; thinner public program documentation than the group''s leaders.", "niche_fit": "A countertop appliance that visibly turns scraps into soil in hours is a satisfying demo for kitchen, home and sustainability creators.", "opportunity_availability": "Listed as an active Impact program with applications open now, subject to brand approval.", "ugc_evidence": "A standing Impact program in the home/garden niche; directory-level evidence only, with no creator-branded program page found."}'::jsonb);
